import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { initializeInvoices, invoiceSnapshot, importBlueCrossMessages, correctInvoice, collectInvoices } from '../../apps/worker/dist/invoices.js';
const email = 'test@example.test';
const ids = ['aabbccdd', 'eeff0011'];
const html = 'x'.repeat(16000) + `<table id="grdClaimsGrid"><th>Amount Claimed</th><th>Amount Paid</th><tr rowId="0"><td>Sep 03, 2026</td><td>Jasmine Wing</td><td>Physio 30 Minutes</td><td>$100.00</td><td>$80.00</td><td>Sep 04, 2026</td><td>Details</td></tr><tfoot><tr><td>Page 1 Total Grand Total</td><td><div>$100.00</div><div>$100.00</div></td><td><div>$80.00</div><div>$80.00</div></td></tr></tfoot></table>`;
const dependencies = { credentials: async () => ({ accounts: [{ email, label: 'Test' }] }), accessToken: async () => 'synthetic', gmail: async (_token, path) => {
  if (path.startsWith('messages?')) return { messages: ids.map(id => ({ id })) };
  const id = path.split('/')[1].split('?')[0];
  return { id, threadId: 'thread', payload: { headers: [{ name: 'Subject', value: 'Blue Cross refund' }], parts: [{ mimeType: 'text/plain', body: { data: Buffer.from(id === 'badbad00' ? 'not a portal export' : html).toString('base64url') } }] } };
} };
await initializeInvoices();
const preview = await importBlueCrossMessages(email, ids, false, dependencies);
assert.equal(preview.uniqueRows, 1); assert.equal(preview.repeatedRows, 1);
assert.equal((await invoiceSnapshot()).items.length, 0);
await assert.rejects(importBlueCrossMessages(email, [...ids, 'badbad00'], true, dependencies));
assert.equal((await invoiceSnapshot()).items.length, 0, 'invalid later email must not partially import');
const result = await importBlueCrossMessages(email, ids, true, dependencies);
assert.equal(result.paid, 80); assert.ok(result.backup);
assert.equal(JSON.parse(await readFile(join(process.env.FAMILYHUB_WORKER_DATA, result.backup), 'utf8')).items.length, 0);
assert.equal((await invoiceSnapshot()).items.length, 3);
const claim = (await invoiceSnapshot()).items.find(item => item.StructuredSource);
await correctInvoice(claim.Id, 'ignore');
assert.equal((await importBlueCrossMessages(email, ids, true, dependencies)).newItems, 0);
assert.equal((await invoiceSnapshot()).items.find(item => item.Id === claim.Id).Status, 4);
await collectInvoices({ ...dependencies, classify: async () => { throw new Error('structured exports must not reach AI classification'); } });
assert.equal((await invoiceSnapshot()).items.length, 3);
console.log('PASS: preview, atomic batch, backup, duplicate emails, manual choices, daily collector');
